/**
 * Подключение к SQLite через встроенный `node:sqlite` (Node 22.5+).
 *
 * Мы не импортируем модуль статически: в @types/node 20 типов для node:sqlite
 * ещё нет, а `createRequire` позволяет получить модуль без объявления
 * глобального ambient-модуля (и не конфликтовать с будущими версиями типов).
 */
export interface SqliteRunResult {
  changes: number | bigint;
  lastInsertRowid: number | bigint;
}

export interface SqliteStatement {
  run(...params: any[]): SqliteRunResult;
  get(...params: any[]): any;
  all(...params: any[]): any[];
  iterate(...params: any[]): IterableIterator<any>;
}

export interface SqliteDatabase {
  exec(sql: string): void;
  prepare(sql: string): SqliteStatement;
  close(): void;
}

type DatabaseSyncCtor = new (
  location: string,
  options?: Record<string, unknown>
) => SqliteDatabase;

const nodeRequire = createRequire(import.meta.url);

function loadSqlite(): DatabaseSyncCtor {
  try {
    const mod = nodeRequire("node:sqlite") as { DatabaseSync: DatabaseSyncCtor };
    return mod.DatabaseSync;
  } catch (err: any) {
    throw new Error(
      `node:sqlite недоступен (${err instanceof Error ? err.message : String(err)}). ` +
        "Планировщику требуется Node.js 22.5+ (рекомендуется Node 24).",
    );
  }
}

/** Путь к БД. Переменная окружения нужна только тестам. */
const DEFAULT_DB_FILE = process.env.OPENCODE_SCHEDULER_DB?.trim()
  ? path.resolve(process.env.OPENCODE_SCHEDULER_DB.trim())
  : path.join(PLUGIN_DIR, "scheduler.db");

let dbFile = DEFAULT_DB_FILE;
let db: SqliteDatabase | null = null;
/** Глубина вложенности withTransaction: 0 — транзакции нет, >0 — SAVEPOINT. */
let transactionDepth = 0;

/** Открывает (или переоткрывает) соединение и применяет схему. */
export function initDb(file: string = dbFile): SqliteDatabase {
  if (db && file === dbFile) return db;
  if (db) closeDb();

  dbFile = file;
  fs.mkdirSync(path.dirname(file), { recursive: true });

  const DatabaseSync = loadSqlite();
  const instance = new DatabaseSync(file);

  // busy_timeout ДОЛЖЕН быть установлен до WAL: при одновременном старте
  // нескольких процессов (каждое завершение задачи — отдельный
  // `node record-history`) переключение journal_mode требует эксклюзивной
  // блокировки. Без таймаута SQLite сразу падает с "database is locked".
  instance.exec("PRAGMA busy_timeout = 5000;");
  // WAL — конкурентное чтение во время записи и устойчивость к сбоям.
  // synchronous = NORMAL в WAL гарантирует, что закоммиченная транзакция
  // переживает падение процесса (шаг 36.1.b); при потере питания может
  // потеряться только последний коммит — это осознанный компромисс.
  instance.exec("PRAGMA journal_mode = WAL;");
  instance.exec("PRAGMA synchronous = NORMAL;");
  instance.exec("PRAGMA foreign_keys = ON;");
  applySchema(instance);

  db = instance;
  return instance;
}

/** Singleton-соединение. Создаётся лениво при первом обращении. */
export function getDb(): SqliteDatabase {
  return db ?? initDb();
}

/** Закрывает соединение (вызывается при выгрузке плагина). */
export function closeDb(): void {
  transactionDepth = 0;
  if (!db) return;
  try {
    db.exec("PRAGMA wal_checkpoint(TRUNCATE);");
  } catch {
    // Чекпойнт не критичен при закрытии.
  }
  try {
    db.close();
  } catch {
    // Соединение могло быть уже закрыто.
  }
  db = null;
}

/** Текущий путь к файлу БД. */
export function getDbFile(): string {
  return dbFile;
}

/** Сбрасывает WAL в основной файл — нужно перед отдачей .db наружу. */
export function checkpointDb(): void {
  getDb().exec("PRAGMA wal_checkpoint(TRUNCATE);");
}

/** Информация о хранилище для /api/health и футера дашборда. */
export function getDbStatus(): {
  engine: "sqlite";
  file: string;
  journalMode: string;
  wal: boolean;
  schemaVersion: number;
  expectedSchemaVersion: number;
  } {
  let journalMode = "unknown";
  let schemaVersion = 0;
  try {
    const row = getDb().prepare("PRAGMA journal_mode;").get();
    journalMode = String(row?.journal_mode ?? "unknown");
    schemaVersion = getSchemaVersion(getDb());
  } catch {
    // Если БД ещё не открыта — не роняем health-check.
  }
  return {
    engine: "sqlite",
    file: dbFile,
    journalMode,
    wal: journalMode.toLowerCase() === "wal",
    schemaVersion,
    expectedSchemaVersion: SCHEMA_VERSION,
  };
}

/**
 * Выполняет функцию в транзакции BEGIN IMMEDIATE.
 * При любой ошибке откатывает изменения и пробрасывает исключение дальше.
 *
 * Вложенный вызов не открывает вторую транзакцию (SQLite это запрещает), а
 * создаёт SAVEPOINT: так композиция вроде «retry из DLQ → reopenRun → retryStep»
 * остаётся атомарной, а внутренний откат не рушит внешнюю транзакцию.
 */
export function withTransaction<T>(fn: () => T): T {
  const instance = getDb();

  if (transactionDepth > 0) {
    const savepoint = `sp_nested_${transactionDepth}`;
    instance.exec(`SAVEPOINT ${savepoint};`);
    transactionDepth += 1;
    try {
      const result = fn();
      instance.exec(`RELEASE ${savepoint};`);
      return result;
    } catch (err) {
      try {
        instance.exec(`ROLLBACK TO ${savepoint};`);
        instance.exec(`RELEASE ${savepoint};`);
      } catch {
        // SAVEPOINT уже снят вместе с внешней транзакцией.
      }
      throw err;
    } finally {
      transactionDepth -= 1;
    }
  }

  instance.exec("BEGIN IMMEDIATE;");
  transactionDepth = 1;
  try {
    const result = fn();
    instance.exec("COMMIT;");
    return result;
  } catch (err) {
    try {
      instance.exec("ROLLBACK;");
    } catch {
      // Откат мог не понадобиться (например, SQLite уже откатил сам).
    }
    throw err;
  } finally {
    transactionDepth = 0;
  }
}

/** Пуста ли БД (не считая служебных настроек вроде retry_state). */
export function isDatabaseEmpty(): boolean {
  const row = getDb()
    .prepare(
      `SELECT
         (SELECT COUNT(*) FROM tasks) +
         (SELECT COUNT(*) FROM history) +
         (SELECT COUNT(*) FROM metrics) +
         (SELECT COUNT(*) FROM templates) AS count`,
    )
    .get();
  return Number(row?.count) === 0;
}

import { WindowsScheduler } from "./windows.js";
import { LinuxScheduler } from "./linux.js";
import { MacScheduler } from "./mac.js";
import type { SchedulerBackend } from "./types.js";

export type {
  SchedulerBackend,
  CreateTaskOptions,
  RunTaskResult,
  TriggerType,
} from "./types.js";
export { WindowsScheduler, SchtasksError, WINDOWS_TASK_PREFIX } from "./windows.js";
export { LinuxScheduler } from "./linux.js";
export { MacScheduler } from "./mac.js";
export { TaskRegistry } from "./registry.js";
export type { RegistryEntry } from "./registry.js";

/**
 * Фабрика бэкендов планировщика по платформе.
 *
 *  - win32  → WindowsScheduler (schtasks);
 *  - darwin → MacScheduler (launchd);
 *  - linux (и прочие POSIX) → LinuxScheduler (crontab).
 */
export function createSchedulerBackend(
  platform: NodeJS.Platform = process.platform,
  profile?: string,
): SchedulerBackend {
  if (platform === "win32") return new WindowsScheduler(profile);
  if (platform === "darwin") return new MacScheduler(profile);
  return new LinuxScheduler(profile);
}

/**
 * Бэкенд планировщика в пространстве имён конкретного профиля — в том числе
 * неактивного. Нужен, чтобы удаление профиля снимало ЕГО задачи, а не задачи
 * активного профиля (T-05).
 */
export function createSchedulerBackendForProfile(
  profile: string,
  platform: NodeJS.Platform = process.platform,
): SchedulerBackend {
  return createSchedulerBackend(platform, profile);
}

/**
 * Снимает все задачи профиля из планировщика ОС перед удалением его файлов.
 * Ошибки по отдельным задачам игнорируются; бросает только если сам список
 * задач получить не удалось.
 */
export async function removeScheduledTasksForProfile(
  profile: string,
  platform: NodeJS.Platform = process.platform,
): Promise<number> {
  const scheduler = createSchedulerBackendForProfile(profile, platform);
  const tasks = await scheduler.listTasks();
  let removed = 0;
  for (const task of tasks) {
    const name = task.taskName ?? "";
    if (!name) continue;
    try {
      await scheduler.deleteTask(name);
      removed++;
    } catch {
      // Задача уже удалена или недоступна — продолжаем чистить остальные.
    }
  }
  return removed;
}

let cached: SchedulerBackend | null = null;

/** Возвращает общий (закэшированный) бэкенд текущей платформы. */
export function getSchedulerBackend(): SchedulerBackend {
  if (!cached) cached = createSchedulerBackend();
  return cached;
}

/** Название планировщика для текущей платформы (для GUI/логов). */
export function getSchedulerTitle(platform: NodeJS.Platform = process.platform): string {
  return createSchedulerBackend(platform).title;
}
